# `HOME is "..." expected "/home/sauyon"`. Hosts that differ declare it in their
# `machine` attrset in flake.nix; the getEnv path stays for impure evaluation.
home.username =
  machine.username or (let v = builtins.getEnv "USER"; in if v != "" then v else "sauyon");
home.homeDirectory =
  machine.homeDir or (
    let v = builtins.getEnv "HOME";
    in if v != "" then v else (if isDarwin then "/Users/sauyon" else "/home/sauyon")
  );

